/*
 * i.MX I2C controller (IMX8MMRM chapter 16.1 "I2C"), master mode, polled.
 *
 * Registers are 16 bits wide on a 4-byte stride: IADR 0x0, IFDR 0x4,
 * I2CR 0x8, I2SR 0xc, I2DR 0x10. A START is generated by setting
 * I2CR.MSTA, every byte transfer ends with I2SR.IIF (cleared by writing 0),
 * and I2SR.RXAK tells whether the slave acknowledged.
 *
 * SPDX-License-Identifier: AGPL-3.0-or-later
 */

#include "i2c.h"
#include "imx8mm.h"

#define IFDR        0x04
#define I2CR        0x08
#define I2SR        0x0c
#define I2DR        0x10

#define I2CR_IEN    0x80
#define I2CR_MSTA   0x20
#define I2CR_MTX    0x10
#define I2CR_TXAK   0x08
#define I2CR_RSTA   0x04
#define I2SR_IBB    0x20
#define I2SR_IIF    0x02
#define I2SR_RXAK   0x01

/* Bound for polling loops, so a missing controller cannot hang the demo */
#define I2C_POLL    100000

static uint32_t i2c_base(int bus)
{
    return I2C1_BASE + (uint32_t)(bus - 1) * 0x10000;
}

static int i2c_wait(uint32_t b, uint16_t mask, uint16_t want)
{
    for (int i = 0; i < I2C_POLL; i++) {
        if ((rd16(b + I2SR) & mask) == want) {
            return 0;
        }
    }
    return -1;
}

/* Send one byte and wait for the end of the transfer; 0 = ACK */
static int i2c_tx(uint32_t b, uint8_t byte)
{
    wr16(b + I2DR, byte);
    if (i2c_wait(b, I2SR_IIF, I2SR_IIF)) {
        return -1;
    }
    wr16(b + I2SR, 0);
    return (rd16(b + I2SR) & I2SR_RXAK) ? -1 : 0;
}

static void i2c_stop(uint32_t b)
{
    wr16(b + I2CR, I2CR_IEN);
    i2c_wait(b, I2SR_IBB, 0);
}

void i2c_init(int bus)
{
    uint32_t b = i2c_base(bus);

    wr16(b + I2CR, 0);
    wr16(b + IFDR, 0x0f);   /* IPG / 240: 100 kHz class from a 24 MHz root */
    wr16(b + I2CR, I2CR_IEN);
    wr16(b + I2SR, 0);
}

int i2c_probe(int bus, uint8_t addr)
{
    uint32_t b = i2c_base(bus);
    int ack;

    wr16(b + I2CR, I2CR_IEN | I2CR_MSTA | I2CR_MTX);
    if (i2c_wait(b, I2SR_IBB, I2SR_IBB)) {
        i2c_stop(b);
        return 0;
    }
    ack = i2c_tx(b, addr << 1) == 0;
    i2c_stop(b);
    return ack;
}

int i2c_read_reg(int bus, uint8_t addr, uint8_t reg, uint8_t *buf, int len)
{
    uint32_t b = i2c_base(bus);
    uint16_t cr = I2CR_IEN | I2CR_MSTA | I2CR_MTX;

    wr16(b + I2CR, cr);
    if (i2c_wait(b, I2SR_IBB, I2SR_IBB) || i2c_tx(b, addr << 1) ||
        i2c_tx(b, reg)) {
        i2c_stop(b);
        return -1;
    }
    /* Repeated start, address with the read bit */
    wr16(b + I2CR, cr | I2CR_RSTA);
    if (i2c_tx(b, (addr << 1) | 1)) {
        i2c_stop(b);
        return -1;
    }
    cr &= ~I2CR_MTX;
    if (len == 1) {
        cr |= I2CR_TXAK;
    }
    wr16(b + I2CR, cr);
    (void)rd16(b + I2DR);       /* dummy read starts the first byte */
    for (int i = 0; i < len; i++) {
        if (i2c_wait(b, I2SR_IIF, I2SR_IIF)) {
            i2c_stop(b);
            return -1;
        }
        wr16(b + I2SR, 0);
        if (i == len - 1) {
            wr16(b + I2CR, I2CR_IEN);       /* STOP before the last read */
        } else if (i == len - 2) {
            wr16(b + I2CR, cr | I2CR_TXAK); /* NAK the last byte */
        }
        buf[i] = rd16(b + I2DR);
    }
    i2c_wait(b, I2SR_IBB, 0);
    return 0;
}
